import "server-only";
import { readFileSync, statSync } from "node:fs";
import path from "node:path";
import { type Facets, type FacetValue, type Filters, CONCENTRATIONS, GENDERS, PRICE_BANDS, SORTS, type SortId } from "./filters";
import { CATEGORIES, CATEGORY_BY_ID, type CollectionId, findSub } from "./taxonomy";
import type { Brand, CardProduct, Product } from "./types";

// The catalog is generated by `npm run import` into data/catalog.json and read once per server process. In
// development a newer file (a fresh import) is picked up on the next request.

const FILE = path.join(process.cwd(), "data", "catalog.json");

export type NavSub = { id: string; name: string; group?: string; count: number };
export type NavCategory = { id: string; name: string; intro: string; count: number; subs: NavSub[] };

type Store = {
  products: Product[];
  bySlug: Map<string, Product>;
  bySku: Map<string, Product>;
  families: Map<string, Product[]>;
  /** Search text per product: names, brand and category words, in both alphabets. */
  haystack: Map<Product, string>;
  brands: Brand[];
  brandBySlug: Map<string, Brand>;
  /** Cards (a family counts once) per "category", "category/sub" and "#tag". */
  counts: Map<string, number>;
  nav: NavCategory[];
  loadedAt: number;
};

let store: Store | null = null;
let checkedAt = 0;

function load(): Store {
  const products = JSON.parse(readFileSync(FILE, "utf8")) as Product[];
  const bySlug = new Map<string, Product>();
  const bySku = new Map<string, Product>();
  const families = new Map<string, Product[]>();
  const haystack = new Map<Product, string>();
  const brandMap = new Map<string, Brand & { keys: Set<string> }>();
  const countKeys = new Map<string, Set<string>>();
  const addCount = (key: string, card: string) => {
    let set = countKeys.get(key);
    if (!set) countKeys.set(key, (set = new Set()));
    set.add(card);
  };

  for (const p of products) {
    bySlug.set(p.slug, p);
    bySku.set(p.sku, p);
    if (p.family) {
      const list = families.get(p.family) ?? [];
      list.push(p);
      families.set(p.family, list);
    }
    const cat = CATEGORY_BY_ID.get(p.category);
    const sub = findSub(p.category, p.sub);
    const words = `${p.brand} ${p.name} ${cat?.name ?? ""} ${sub?.name ?? ""} ${p.ean} ${p.sku}`.toLowerCase().replace(/ё/g, "е");
    haystack.set(p, `${words} | ${toLatin(words)} | ${toCyrillic(words)}`);
    const card = cardKey(p);
    addCount(p.category, card);
    addCount(`${p.category}/${p.sub}`, card);
    for (const t of p.tags) addCount(`#${t}`, card);
    if (p.brandSlug) {
      const b = brandMap.get(p.brandSlug) ?? { slug: p.brandSlug, name: p.brand, count: 0, keys: new Set<string>() };
      b.keys.add(card);
      b.count = b.keys.size;
      brandMap.set(p.brandSlug, b);
    }
  }
  for (const list of families.values()) list.sort((a, b) => naturalCompare(a.variant ?? "", b.variant ?? ""));

  const counts = new Map<string, number>();
  for (const [k, set] of countKeys) counts.set(k, set.size);
  const brands = [...brandMap.values()]
    .map(({ slug, name, count }) => ({ slug, name, count }))
    .sort((a, b) => b.count - a.count || a.name.localeCompare(b.name, "bg"));

  const nav: NavCategory[] = CATEGORIES.map((c) => ({
    id: c.id,
    name: c.name,
    intro: c.intro,
    count: counts.get(c.id) ?? 0,
    subs: c.subs.map((s) => ({ ...s, count: counts.get(`${c.id}/${s.id}`) ?? 0 })).filter((s) => s.count > 0),
  })).filter((c) => c.count > 0);

  return {
    products,
    bySlug,
    bySku,
    families,
    haystack,
    brands,
    brandBySlug: new Map(brands.map((b) => [b.slug, b])),
    counts,
    nav,
    loadedAt: Date.now(),
  };
}

function db(): Store {
  if (!store) {
    store = load();
    checkedAt = Date.now();
  } else if (process.env.NODE_ENV !== "production" && Date.now() - checkedAt > 3000) {
    checkedAt = Date.now();
    try {
      if (statSync(FILE).mtimeMs > store.loadedAt) store = load();
    } catch {
      // Keep the catalog already in memory.
    }
  }
  return store;
}

// ── Small helpers ──

const LAT: Record<string, string> = {
  а: "a", б: "b", в: "v", г: "g", д: "d", е: "e", ж: "zh", з: "z", и: "i", й: "y", к: "k", л: "l", м: "m", н: "n", о: "o", п: "p",
  р: "r", с: "s", т: "t", у: "u", ф: "f", х: "h", ц: "ts", ч: "ch", ш: "sh", щ: "sht", ъ: "a", ь: "y", ю: "yu", я: "ya",
};
const CYR: [RegExp, string][] = [
  [/sht/g, "щ"], [/sh/g, "ш"], [/ch/g, "ч"], [/zh/g, "ж"], [/ts/g, "ц"], [/yu/g, "ю"], [/ya/g, "я"], [/ph/g, "ф"], [/th/g, "т"],
  [/a/g, "а"], [/b/g, "б"], [/c/g, "к"], [/d/g, "д"], [/e/g, "е"], [/f/g, "ф"], [/g/g, "г"], [/h/g, "х"], [/i/g, "и"], [/j/g, "дж"],
  [/k/g, "к"], [/l/g, "л"], [/m/g, "м"], [/n/g, "н"], [/o/g, "о"], [/p/g, "п"], [/q/g, "к"], [/r/g, "р"], [/s/g, "с"], [/t/g, "т"],
  [/u/g, "у"], [/v/g, "в"], [/w/g, "в"], [/x/g, "кс"], [/y/g, "й"], [/z/g, "з"],
];

function toLatin(text: string): string {
  return text.replace(/[а-я]/g, (ch) => LAT[ch] ?? ch);
}

function toCyrillic(text: string): string {
  let t = text.normalize("NFKD").replace(/[̀-ͯ]/g, "");
  for (const [re, to] of CYR) t = t.replace(re, to);
  return t;
}

/** "N02" < "N15" < "N119"; "50 мл" < "100 мл". */
export function naturalCompare(a: string, b: string): number {
  return a.localeCompare(b, "bg", { numeric: true, sensitivity: "base" });
}

/** Shades and sizes of one product share a card in listings. */
export function cardKey(p: Product): string {
  return p.family ? `f:${p.family}` : `p:${p.sku}`;
}

const SIZE_LABEL = /^\d+(?:[.,]\d+)?\s?(?:мл|г|л|бр\.?|кг)$/u;

// ── Public lookups ──

export const allProducts = (): readonly Product[] => db().products;
export const productCount = () => db().products.length;
export const inStockCount = () => db().products.reduce((n, p) => n + (p.stock > 0 ? 1 : 0), 0);
export const getProduct = (slug: string) => db().bySlug.get(slug);
export const getBySku = (sku: string) => db().bySku.get(sku);
export const getBrand = (slug: string) => db().brandBySlug.get(slug);
export const allBrands = () => db().brands;
export const navCategories = () => db().nav;
export const countFor = (key: string) => db().counts.get(key) ?? 0;

/** The other shades or sizes of a product, in natural order (the product itself included). */
export function familyOf(p: Product): Product[] {
  return p.family ? (db().families.get(p.family) ?? [p]) : [p];
}

export function variantKind(members: Product[]): "shade" | "size" | null {
  if (members.length < 2) return null;
  return members.every((m) => SIZE_LABEL.test(m.variant ?? "")) ? "size" : "shade";
}

/** Name of the product line without the shade or size ("Color Expert лак за нокти"). */
export function familyName(p: Product): string {
  if (!p.family || !p.variant || !p.name.endsWith(p.variant)) return p.name;
  return p.name.slice(0, p.name.length - p.variant.length).replace(/[\s,.;:\-–|/(]+$/u, "").trim() || p.name;
}

// ── Listings ──

export const PAGE_SIZE = 36;

export type Scope = { category?: string; sub?: string; brand?: string; tag?: CollectionId; q?: string };

export type Card = {
  product: Product;
  /** Shades or sizes the product comes in (1 for a single product). */
  variants: number;
  kind: "shade" | "size" | null;
  minPrice: number;
  maxPrice: number;
  /** Product name shown on the card (the line name when the card stands for several shades). */
  title: string;
};

export type ListResult = { cards: Card[]; total: number; page: number; pages: number; facets: Facets };

export function normalizeQuery(q: string): string[] {
  return q
    .toLowerCase()
    .replace(/ё/g, "е")
    .replace(/[^\p{L}\p{N}\s'-]+/gu, " ")
    .split(/\s+/)
    .map((t) => t.replace(/^['-]+|['-]+$/g, ""))
    .filter((t) => t.length >= 2)
    .slice(0, 6);
}

/** Reads filters from the URL query. Unknown values are ignored instead of failing. */
export function parseFilters(sp: Record<string, string | string[] | undefined>): Filters {
  const one = (k: string) => (Array.isArray(sp[k]) ? sp[k]![0] : (sp[k] as string | undefined)) ?? "";
  const many = (k: string) => one(k).split(",").map((v) => v.trim()).filter(Boolean);
  const sort = (SORTS.some((s) => s.id === one("sort")) ? one("sort") : "") as SortId;
  const brandSlugs = db().brandBySlug;
  return {
    brands: [...new Set(many("brand").filter((b) => brandSlugs.has(b)))].slice(0, 30),
    price: PRICE_BANDS.some((b) => b.id === one("price")) ? one("price") : "",
    stock: one("nalichni") === "1",
    sort,
    page: Math.max(1, Math.min(1000, Math.floor(Number(one("page")) || 1))),
    cat: CATEGORY_BY_ID.has(one("cat")) ? one("cat") : "",
    gender: many("pol").filter((g) => GENDERS.some((x) => x.id === g)),
    conc: many("vid").filter((c) => CONCENTRATIONS.some((x) => x.id === c)),
  };
}

function base(scope: Scope): { items: Product[]; tokens: string[] } {
  const s = db();
  const tokens = scope.q ? normalizeQuery(scope.q) : [];
  if (scope.q !== undefined && !tokens.length) return { items: [], tokens };
  const items = s.products.filter((p) => {
    if (scope.category && p.category !== scope.category) return false;
    if (scope.sub && p.sub !== scope.sub) return false;
    if (scope.brand && p.brandSlug !== scope.brand) return false;
    if (scope.tag && !p.tags.includes(scope.tag)) return false;
    if (tokens.length) {
      const hay = s.haystack.get(p)!;
      if (!tokens.every((t) => hay.includes(t))) return false;
    }
    return true;
  });
  return { items, tokens };
}

function searchScore(p: Product, tokens: string[], phrase: string): number {
  const name = p.name.toLowerCase();
  const brand = p.brand.toLowerCase();
  let score = name.includes(phrase) ? 20 : 0;
  if (brand === phrase) score += 30;
  for (const t of tokens) {
    if (brand.startsWith(t)) score += 8;
    if (name.startsWith(t)) score += 7;
    else if (new RegExp(`(^|[\\s,(-])${t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}`, "u").test(name)) score += 5;
    else if (name.includes(t)) score += 2;
  }
  return score + (p.stock > 0 ? 6 : 0);
}

export function list(scope: Scope, f: Filters): ListResult {
  const { items, tokens } = base(scope);
  const band = PRICE_BANDS.find((b) => b.id === f.price);
  const pass = {
    cat: (p: Product) => !f.cat || p.category === f.cat,
    brand: (p: Product) => !f.brands.length || f.brands.includes(p.brandSlug),
    price: (p: Product) => !band || (p.price >= band.min && p.price < band.max),
    stock: (p: Product) => !f.stock || p.stock > 0,
    gender: (p: Product) => !f.gender.length || (p.facts.gender !== undefined && f.gender.includes(p.facts.gender)),
    conc: (p: Product) => !f.conc.length || (p.facts.conc !== undefined && f.conc.includes(p.facts.conc)),
  };
  type Dim = keyof typeof pass;
  const dims = Object.keys(pass) as Dim[];
  const others = (p: Product, skip: Dim) => dims.every((d) => d === skip || pass[d](p));

  // Each facet counts with every other active filter applied, so its numbers match what a click would show.
  const facetSets = {
    brand: new Map<string, Set<string>>(),
    price: new Map<string, Set<string>>(),
    cat: new Map<string, Set<string>>(),
    gender: new Map<string, Set<string>>(),
    conc: new Map<string, Set<string>>(),
    stock: new Set<string>(),
  };
  const bump = (m: Map<string, Set<string>>, k: string, card: string) => {
    let set = m.get(k);
    if (!set) m.set(k, (set = new Set()));
    set.add(card);
  };
  const matched: Product[] = [];
  for (const p of items) {
    const card = cardKey(p);
    if (p.brandSlug && others(p, "brand")) bump(facetSets.brand, p.brandSlug, card);
    if (others(p, "price")) {
      const pb = PRICE_BANDS.find((x) => p.price >= x.min && p.price < x.max);
      if (pb) bump(facetSets.price, pb.id, card);
    }
    if (others(p, "cat")) bump(facetSets.cat, p.category, card);
    if (p.facts.gender && others(p, "gender")) bump(facetSets.gender, p.facts.gender, card);
    if (p.facts.conc && others(p, "conc")) bump(facetSets.conc, p.facts.conc, card);
    if (p.stock > 0 && others(p, "stock")) facetSets.stock.add(card);
    if (dims.every((d) => pass[d](p))) matched.push(p);
  }

  // One card per product line; the best-ranked matching shade represents it.
  const cardsByKey = new Map<string, Card & { score: number; newest: string }>();
  const phrase = tokens.join(" ");
  for (const p of matched) {
    const key = cardKey(p);
    const existing = cardsByKey.get(key);
    const score = tokens.length ? searchScore(p, tokens, phrase) : 0;
    if (!existing) {
      const members = familyOf(p);
      cardsByKey.set(key, {
        product: p,
        variants: members.length,
        kind: variantKind(members),
        minPrice: p.price,
        maxPrice: p.price,
        title: members.length > 1 ? familyName(p) : p.name,
        score,
        newest: p.created,
      });
      continue;
    }
    existing.minPrice = Math.min(existing.minPrice, p.price);
    existing.maxPrice = Math.max(existing.maxPrice, p.price);
    if (score > existing.score) existing.score = score;
    if (p.created > existing.newest) existing.newest = p.created;
    // Prefer a shade that is in stock to represent the line.
    if (existing.product.stock <= 0 && p.stock > 0) existing.product = p;
  }
  const cards = [...cardsByKey.values()];
  const byRank = (a: Card, b: Card) => b.product.rank - a.product.rank;
  switch (f.sort) {
    case "new":
      cards.sort((a, b) => b.newest.localeCompare(a.newest) || byRank(a, b));
      break;
    case "price-asc":
      cards.sort((a, b) => a.minPrice - b.minPrice || byRank(a, b));
      break;
    case "price-desc":
      cards.sort((a, b) => b.maxPrice - a.maxPrice || byRank(a, b));
      break;
    default:
      if (tokens.length) cards.sort((a, b) => b.score - a.score || byRank(a, b));
    // otherwise the catalog is already in "recommended" order
  }

  const pages = Math.max(1, Math.ceil(cards.length / PAGE_SIZE));
  const page = Math.min(f.page, pages);
  const s = db();
  const facetList = (m: Map<string, Set<string>>, label: (id: string) => string | undefined, keep: string[] = []): FacetValue[] =>
    [...new Set([...m.keys(), ...keep])]
      .map((id) => ({ id, label: label(id) ?? id, count: m.get(id)?.size ?? 0 }))
      .filter((v) => v.label);
  const facets: Facets = {
    brands: facetList(facetSets.brand, (id) => s.brandBySlug.get(id)?.name, f.brands).sort((a, b) => b.count - a.count || a.label.localeCompare(b.label, "bg")),
    prices: PRICE_BANDS.map((b) => ({ id: b.id, label: b.label, count: facetSets.price.get(b.id)?.size ?? 0 })),
    categories: CATEGORIES.filter((c) => facetSets.cat.has(c.id) || f.cat === c.id).map((c) => ({ id: c.id, label: c.name, count: facetSets.cat.get(c.id)?.size ?? 0 })),
    genders: GENDERS.filter((g) => facetSets.gender.has(g.id) || f.gender.includes(g.id)).map((g) => ({ id: g.id, label: g.label, count: facetSets.gender.get(g.id)?.size ?? 0 })),
    concentrations: CONCENTRATIONS.filter((c) => facetSets.conc.has(c.id) || f.conc.includes(c.id)).map((c) => ({ id: c.id, label: c.label, count: facetSets.conc.get(c.id)?.size ?? 0 })),
    inStock: facetSets.stock.size,
  };
  return { cards: cards.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE), total: cards.length, page, pages, facets };
}

/** A single product as a card (for rails on the home and product pages). */
export function cardOf(p: Product): Card {
  const members = familyOf(p);
  const prices = members.map((m) => m.price);
  return {
    product: p,
    variants: members.length,
    kind: variantKind(members),
    minPrice: Math.min(...prices),
    maxPrice: Math.max(...prices),
    title: members.length > 1 ? familyName(p) : p.name,
  };
}

// ── Collections for the home page and product pages ──

type Pick = { categories?: string[]; subs?: string[]; tags?: CollectionId[]; brands?: string[]; perBrand?: number; minSide?: number; exclude?: Set<string> };

/** Best in-stock product lines with a good picture, at most `perBrand` per brand. */
export function featured(limit: number, opts: Pick = {}): Card[] {
  const perBrand = opts.perBrand ?? 2;
  const used = new Map<string, number>();
  const seen = new Set<string>();
  const out: Card[] = [];
  for (const p of db().products) {
    if (out.length >= limit) break;
    if (p.stock <= 0 || Math.min(p.iw, p.ih) < (opts.minSide ?? 400)) continue;
    if (opts.categories && !opts.categories.includes(p.category)) continue;
    if (opts.subs && !opts.subs.includes(p.sub)) continue;
    if (opts.tags && !opts.tags.some((t) => p.tags.includes(t))) continue;
    if (opts.brands && !opts.brands.includes(p.brandSlug)) continue;
    const key = cardKey(p);
    if (seen.has(key) || opts.exclude?.has(key)) continue;
    const b = p.brandSlug || p.sku;
    if ((used.get(b) ?? 0) >= perBrand) continue;
    used.set(b, (used.get(b) ?? 0) + 1);
    seen.add(key);
    out.push(cardOf(p));
  }
  return out;
}

export function newest(limit: number, perBrand = 2): Card[] {
  const sorted = db().products.filter((p) => p.tags.includes("novo")).sort((a, b) => b.created.localeCompare(a.created) || b.rank - a.rank);
  const used = new Map<string, number>();
  const seen = new Set<string>();
  const out: Card[] = [];
  for (const p of sorted) {
    if (out.length >= limit) break;
    if (Math.min(p.iw, p.ih) < 400) continue;
    const key = cardKey(p);
    const b = p.brandSlug || p.sku;
    if (seen.has(key) || (used.get(b) ?? 0) >= perBrand) continue;
    used.set(b, (used.get(b) ?? 0) + 1);
    seen.add(key);
    out.push(cardOf(p));
  }
  return out;
}

/** Similar products: same subcategory, similar price, in stock first, other product lines. */
export function related(p: Product, limit: number): Card[] {
  const own = cardKey(p);
  const pool = db().products.filter((x) => x.category === p.category && x.sub === p.sub && cardKey(x) !== own);
  const seen = new Set<string>();
  return pool
    .map((x) => ({ x, d: Math.abs(Math.log((x.price + 1) / (p.price + 1))) - (x.stock > 0 ? 1 : 0) - (x.brandSlug === p.brandSlug ? 0.15 : 0) }))
    .sort((a, b) => a.d - b.d || b.x.rank - a.x.rank)
    .filter(({ x }) => {
      const k = cardKey(x);
      if (seen.has(k)) return false;
      seen.add(k);
      return true;
    })
    .slice(0, limit)
    .map(({ x }) => cardOf(x));
}

export function fromBrand(p: Product, limit: number): Card[] {
  if (!p.brandSlug) return [];
  const own = cardKey(p);
  const seen = new Set<string>([own]);
  const out: Card[] = [];
  for (const x of db().products) {
    if (out.length >= limit) break;
    if (x.brandSlug !== p.brandSlug || x.stock <= 0) continue;
    const k = cardKey(x);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(cardOf(x));
  }
  return out;
}

/** A clean product picture that stands for a category or subcategory (menus, category tiles). */
export function coverFor(category: string, sub?: string, skip = 3): Product | undefined {
  const pool = db().products.filter(
    (p) => p.category === category && (!sub || p.sub === sub) && p.stock > 0 && Math.min(p.iw, p.ih) >= 500 && /lillydrogerie|notinoimg|dm-static|ozone/.test(p.image),
  );
  return pool[skip] ?? pool[0] ?? db().products.find((p) => p.category === category && (!sub || p.sub === sub));
}

// ── Search suggestions ──

export type Suggestion = {
  products: CardProduct[];
  brands: { name: string; slug: string; count: number }[];
  categories: { label: string; href: string; count: number }[];
  total: number;
};

export function suggest(q: string): Suggestion {
  const tokens = normalizeQuery(q);
  if (!tokens.length) return { products: [], brands: [], categories: [], total: 0 };
  const result = list({ q }, { brands: [], price: "", stock: false, sort: "", page: 1, cat: "", gender: [], conc: [] });
  const matches = (words: string) => {
    const w = `${words} ${toLatin(words)} ${toCyrillic(words)}`.toLowerCase();
    return tokens.every((t) => w.includes(t));
  };
  const categories: Suggestion["categories"] = [];
  for (const c of navCategories()) {
    if (matches(c.name)) categories.push({ label: c.name, href: `/${c.id}`, count: c.count });
    for (const sub of c.subs) if (matches(sub.name)) categories.push({ label: `${sub.name}`, href: `/${c.id}/${sub.id}`, count: sub.count });
  }
  const brands = allBrands()
    .filter((b) => matches(b.name))
    .slice(0, 3)
    .map((b) => ({ name: b.name, slug: b.slug, count: b.count }));
  return { products: result.cards.slice(0, 6).map((c) => toCard(c.product, c.title)), brands, categories: categories.slice(0, 4), total: result.total };
}

/** The part of a product that client components (cart, search suggestions, favourites) need. */
export function toCard(p: Product, title?: string): CardProduct {
  return { sku: p.sku, slug: p.slug, name: title ?? p.name, brand: p.brand, price: p.price, image: p.image, stock: p.stock, variant: p.variant };
}
